import json
import math

# Input data
n_slots = 9  # The amount of slots on a template
n_templates = 2  # The amount of templates
n_var = 7  # The amount of different variations
demand = [250, 255, 260, 500, 500, 800, 1100]  # The demand per variation

# Compute an upper bound on production for each template
max_demand = max(demand)

# Model definition
model = cp_model.CpModel()

# Decision Variables

# b[t][s][v] = 1 if on template t, slot s is assigned variation v
b = [
    [
        [model.NewBoolVar(f"b_{t}_{s}_{v}") for v in range(n_var)]
        for s in range(n_slots)
    ]
    for t in range(n_templates)
]

# k[t][v] = number of slots of variation v on template t
k = [
    [model.NewIntVar(0, n_slots, f"k_{t}_{v}") for v in range(n_var)]
    for t in range(n_templates)
]

# P[t] = number of sheets to print of template t
P = [
    model.NewIntVar(0, max_demand, f"P_{t}")
    for t in range(n_templates)
]

# z[t][v] = total items of variation v produced by template t = P[t] * k[t][v]
z = [
    [
        model.NewIntVar(0, n_slots * max_demand, f"z_{t}_{v}")
        for v in range(n_var)
    ]
    for t in range(n_templates)
]

# Constraints

# Each slot on each template must be assigned exactly one variation
for t in range(n_templates):
    for s in range(n_slots):
        model.Add(sum(b[t][s][v] for v in range(n_var)) == 1)

# Link k and b: count how many slots of each variation on each template
for t in range(n_templates):
    for v in range(n_var):
        model.Add(k[t][v] == sum(b[t][s][v] for s in range(n_slots)))

# A template cannot have more assignments than available slots
for t in range(n_templates):
    model.Add(sum(k[t][v] for v in range(n_var)) <= n_slots)

# Define z[t][v] = P[t] * k[t][v]
for t in range(n_templates):
    for v in range(n_var):
        model.AddMultiplicationEquality(z[t][v], [P[t], k[t][v]])

# Ensure demand for each variation is met
for v in range(n_var):
    model.Add(sum(z[t][v] for t in range(n_templates)) >= demand[v])

# Objective function: minimize total number of sheets printed
model.Minimize(sum(P[t] for t in range(n_templates)))

# Solve the model
solver = cp_model.CpSolver()
status = solver.Solve(model)

# Print the solution in the required JSON format
if status == cp_model.OPTIMAL or status == cp_model.FEASIBLE:
    production = [solver.Value(P[t]) for t in range(n_templates)]
    layout = []
    for t in range(n_templates):
        slots = []
