for w in range(n_weeks):
    for i in range(n_golfers):
        model.Add(
            sum(is_in[w, g, i] for g in range(n_groups))
            == 1
        )

# 2) Each group has exactly group_size golfers each week
for w in range(n_weeks):
    for g in range(n_groups):
        model.Add(
            sum(is_in[w, g, i] for i in range(n_golfers))
            == group_size
        )

# 3) No pair of golfers plays together more than once
#    We introduce common[w][g][i][j] = is_in[w,g,i] AND is_in[w,g,j]
common = {}
for w in range(n_weeks):
    for g in range(n_groups):
        for i in range(n_golfers):
            for j in range(i + 1, n_golfers):
