from ortools.sat.python import cp_model
import json

# Input data
n_boats = 5  # Number of boats
n_periods = 4  # Number of periods
capacity = [6, 8, 12, 12, 12]  # Capacities of the boats
crew_size = [2, 2, 2, 2, 4]  # Crew sizes of the boats

# Model definition
model = cp_model.CpModel()

# Decision Variables
# is_host[i] == 1 if boat i is designated as a host
is_host = [model.NewBoolVar(f"is_host[{i}]") for i in range(n_boats)]

# visits[p][i][h] == 1 if in period p, boat i (guest) visits boat h (host)
visits = []
for p in range(n_periods):
    vp = []
    for i in range(n_boats):
        vp.append([model.NewBoolVar(f"visits[{p}][{i}][{h}]") for h in range(n_boats)])
    visits.append(vp)

# meeting[p][i][j][h] == 1 if in period p, guests i and j both visit host h
meeting = {}
for p in range(n_periods):
    for i in range(n_boats):
        for j in range(i+1, n_boats):
            for h in range(n_boats):
                m = model.NewBoolVar(f"meet[{p}][{i}][{j}][{h}]")
                meeting[(p, i, j, h)] = m
                # Enforce m -> both visits
                model.Add(m <= visits[p][i][h])
                model.Add(m <= visits[p][j][h])
                # If both visits then m = 1
                model.Add(visits[p][i][h] + visits[p][j][h] - m <= 1)

# Constraints

# 1) A boat either is a host (then makes no visits) or is a guest (visits exactly one host per period)
for i in range(n_boats):
    for p in range(n_periods):
        # sum_h visits[p][i][h] + is_host[i] == 1
        model.Add(sum(visits[p][i][h] for h in range(n_boats)) + is_host[i] == 1)
    # Prevent self-visits
    for p in range(n_periods):
        model.Add(visits[p][i][i] == 0)

# 2) A guest can only visit a designated host
for p in range(n_periods):
    for i in range(n_boats):
        for h in range(n_boats):
            model.Add(visits[p][i][h] <= is_host[h])

# 3) Capacity constraints: host crew + visiting crews <= capacity
for h in range(n_boats):
    for p in range(n_periods):
        model.Add(
            sum(crew_size[i] * visits[p][i][h] for i in range(n_boats)) 
            <= capacity[h] - crew_size[h]
        )

# 4) No guest revisits the same host more than once
for i in range(n_boats):
    for h in range(n_boats):
        model.Add(sum(visits[p][i][h] for p in range(n_periods)) <= 1)

# 5) No two guest crews meet more than once
for i in range(n_boats):
    for j in range(i+1, n_boats):
        model.Add(
            sum(meeting[(p, i, j, h)] for p in range(n_periods) for h in range(n_boats)) 
            <= 1
        )

# Objective: minimize the number of hosts
model.Minimize(sum(is_host))

# Solve the model
solver = cp_model.CpSolver()
status = solver.Solve(model)

# Output
if status == cp_model.OPTIMAL or status == cp_model.FEASIBLE:
    solution = {
        "visits": [
