    1: [0, 4],  # Paper (2) beats Rock (1) and Spock (5)
    2: [1, 3],  # Scissors (3) beats Paper (2) and Lizard (4)
    3: [1, 4],  # Lizard (4) beats Paper (2) and Spock (5)
    4: [0, 2],  # Spock (5) beats Rock (1) and Scissors (3)
}

