num_dice = 5
faces_per_die = 6
dice = [
    [model.NewIntVar(0, 10, f"dice_{d}_{i}") for i in range(faces_per_die)]
    for d in range(num_dice)
]

# Enforce non-decreasing order on each die's faces for symmetry breaking
for d in range(num_dice):
    for i in range(faces_per_die - 1):
        model.Add(dice[d][i] <= dice[d][i + 1])

# Win counts: wins[d1][d2] is the count of face-to-face wins of die d1 over die d2
wins = [
    [model.NewIntVar(0, faces_per_die * faces_per_die, f"wins_{d1}_{d2}")
     for d2 in range(num_dice)]
    for d1 in range(num_dice)
]

# Boolean indicators b[d1][d2][i][j] is True iff dice[d1][i] > dice[d2][j]
b = {}
for d1 in range(num_dice):
    for d2 in range(num_dice):
        if d1 == d2:
            continue
        for i in range(faces_per_die):
            for j in range(faces_per_die):
                bv = model.NewBoolVar(f"b_{d1}_{d2}_{i}_{j}")
                b[(d1, d2, i, j)] = bv
                # If bv is True then face d1,i > face d2,j; otherwise <=
                model.Add(dice[d1][i] > dice[d2][j]).OnlyEnforceIf(bv)
                model.Add(dice[d1][i] <= dice[d2][j]).OnlyEnforceIf(bv.Not())
        # Link the sum of booleans to wins[d1][d2]
        model.Add(wins[d1][d2] == sum(b[(d1, d2, i, j)]
